'use client';

import * as React from 'react';
import { type MotionMode } from '@/hooks/use-on-twos';
import { Badge } from './badge';

export interface ToneBarItem {
  id: string;
  name: string;
  value: number;
  formattedValue?: string;
  share?: number;
  badge?: string;
}

export interface ToneBarListProps {
  title?: string;
  subtitle?: string;
  items: ToneBarItem[];
  selectedId?: string | null;
  onSelect?: (id: string | null) => void;
  motion?: MotionMode;
  changed?: boolean;
  idPrefix?: string;
  className?: string;
}

export function ToneBarList({
  title,
  subtitle,
  items,
  selectedId = null,
  onSelect,
  changed = false,
  idPrefix = 'f12',
  className = '',
}: ToneBarListProps) {
  const max = Math.max(1, ...items.map((r) => r.value));
  const listKey = items.map((r) => `${r.id}:${r.value}`).join('|');

  return (
    <div className={`ints${className ? ` ${className}` : ''}`}>
      {(title || subtitle) && (
        <div className="ints-hd">
          {title && <h3 className="m-label">{title}</h3>}
          {subtitle && <p className="ints-sub">{subtitle}</p>}
        </div>
      )}
      <ul className={`ints-list${changed ? ' enter' : ''}`} key={listKey}>
        {items.map((r) => {
          const on = selectedId === r.id;
          const formatted = r.formattedValue ?? '$' + Math.round(r.value).toLocaleString('en-US');
          return (
            <li key={r.id}>
              <button
                type="button"
                id={idPrefix ? `int-${idPrefix}-${r.id}` : `int-${r.id}`}
                className="int-row"
                aria-pressed={on}
                onClick={() => onSelect?.(on ? null : r.id)}
              >
                <span className="int-name">
                  {r.name}
                  {r.badge && (
                    <Badge pop={changed} burst>
                      {r.badge}
                    </Badge>
                  )}
                </span>
                <span className="int-bar" aria-hidden="true">
                  <span className="int-fill" style={{ width: `${(r.value / max) * 100}%` }} />
                </span>
                <span className="int-val">
                  {formatted}
                  {r.share != null && (
                    <span className="int-share">{(r.share * 100).toFixed(0)}%</span>
                  )}
                </span>
              </button>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

'use client';

import * as React from 'react';

export interface BadgeProps extends React.HTMLAttributes<HTMLSpanElement> {
  pop?: boolean;
  burst?: boolean;
  children?: React.ReactNode;
}

export function Burst() {
  const lines: React.ReactElement[] = [];
  for (let i = 0; i < 14; i++) {
    const a = (i / 14) * Math.PI * 2;
    const r1 = 15 + (i % 2) * 3;
    const r2 = 25 + (i % 3) * 3;
    lines.push(
      <line
        key={i}
        x1={30 + Math.cos(a) * r1 * 1.9}
        y1={14 + Math.sin(a) * r1 * 0.75}
        x2={30 + Math.cos(a) * r2 * 1.9}
        y2={14 + Math.sin(a) * r2 * 0.75}
      />,
    );
  }
  return (
    <svg className="burst" viewBox="-20 -12 100 52" aria-hidden="true">
      {lines}
    </svg>
  );
}

export function Badge({
  pop = false,
  burst = true,
  className = '',
  children,
  ...rest
}: BadgeProps) {
  return (
    <span className={`badge${pop ? ' pop' : ''}${className ? ` ${className}` : ''}`} {...rest}>
      {burst && <Burst />}
      <span className="badge-t">{children}</span>
    </span>
  );
}

'use client';

import * as React from 'react';

export type MotionMode = 'stepped' | 'smooth' | 'cut';

export const FRAME_MS = 1000 / 12; // animating "on twos": 12 drawings per second (83.33ms per pose)

const easeOut = (t: number): number => 1 - Math.pow(1 - t, 3);

const useIsoLayoutEffect = typeof window !== 'undefined' ? React.useLayoutEffect : React.useEffect;

export function useSize(ref: { readonly current: HTMLElement | null }): { w: number; h: number } {
  const [size, setSize] = React.useState<{ w: number; h: number }>({ w: 0, h: 0 });

  useIsoLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    // Layout size (offsetWidth/Height), not the transformed box, so scaled previews draw correctly.
    const measure = () => {
      const w = el.offsetWidth;
      const h = el.offsetHeight;
      setSize((s) => (s.w === w && s.h === h ? s : { w, h }));
    };
    measure();
    if (typeof ResizeObserver === 'undefined') return;
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, [ref]);

  return size;
}

export function useReducedMotion(): boolean {
  const [reduced, setReduced] = React.useState<boolean>(() => {
    if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') return false;
    return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  });

  React.useEffect(() => {
    if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') return;
    const q = window.matchMedia('(prefers-reduced-motion: reduce)');
    setReduced(q.matches);
    const on = () => setReduced(q.matches);
    if (q.addEventListener) {
      q.addEventListener('change', on);
      return () => q.removeEventListener('change', on);
    }
    q.addListener(on);
    return () => q.removeListener(on);
  }, []);

  return reduced;
}

/**
 * Progress 0..1 that replays whenever `key` changes.
 * Stepped mode samples the easing curve at 12 poses per second (83.33ms per pose),
 * like an animation spacing chart. Honors `prefers-reduced-motion: reduce`.
 */
export function useOnTwos(
  key: unknown,
  duration = 600,
  motion: MotionMode = 'stepped',
): number {
  const reduced = useReducedMotion();
  const effectiveMotion: MotionMode = reduced ? 'cut' : motion;
  const [p, setP] = React.useState<number>(1);
  const first = React.useRef<boolean>(true);

  useIsoLayoutEffect(() => {
    if (first.current) {
      first.current = false;
      return;
    }
    if (effectiveMotion === 'cut') {
      setP(1);
      return;
    }
    const start = performance.now();
    const frames = Math.max(2, Math.round(duration / FRAME_MS));
    let raf = 0;
    let last = -1;
    const tick = (now: number) => {
      const el = now - start;
      let t: number;
      if (effectiveMotion === 'stepped') {
        const k = Math.min(frames, Math.floor(el / FRAME_MS) + 1);
        t = k / frames;
      } else {
        t = Math.min(1, el / duration);
      }
      const v = easeOut(t);
      if (v !== last) {
        last = v;
        setP(v);
      }
      if (t < 1) raf = requestAnimationFrame(tick);
    };
    setP(effectiveMotion === 'stepped' ? easeOut(1 / frames) : 0);
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [key, duration, effectiveMotion]);

  return p;
}

export const useTween = useOnTwos;

export function useCountUp(
  value: number,
  motion: MotionMode = 'stepped',
  duration = 600,
): number {
  const prev = React.useRef<number>(value);
  const from = React.useRef<number>(value);
  if (prev.current !== value) {
    from.current = prev.current;
    prev.current = value;
  }
  const p = useOnTwos(value, duration, motion);
  return from.current + (value - from.current) * p;
}

/**
 * Becomes true after the first change of `key`, so entrance animations
 * never run on first paint (the page is complete at rest).
 */
export function useChanged(key: unknown): boolean {
  const first = React.useRef<unknown>(key);
  const [changed, setChanged] = React.useState<boolean>(false);
  React.useEffect(() => {
    if (key !== first.current) setChanged(true);
  }, [key]);
  return changed;
}
